<?php
declare(strict_types=1);
session_start(); require __DIR__ . '/config.php'; require_login();
$pdo=db(); $from=(string)($_GET['from'] ?? date('Y-m-01')); $to=(string)($_GET['to'] ?? date('Y-m-d')); $employee=(int)($_GET['employee_id'] ?? 0);
foreach (['from'=>&$from,'to'=>&$to] as &$d) { if (!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d)) $d=date('Y-m-d'); } unset($d);
$employees=$pdo->query('SELECT id,employee_no,full_name FROM employees ORDER BY full_name')->fetchAll();
$sql='SELECT a.attendance_date,e.employee_no,e.full_name,a.status,a.time_in,a.time_out,a.notes FROM attendance a JOIN employees e ON e.id=a.employee_id WHERE a.attendance_date BETWEEN ? AND ?'; $params=[$from,$to];
if ($employee>0) { $sql.=' AND e.id=?'; $params[]=$employee; } $sql.=' ORDER BY a.attendance_date DESC,e.full_name';
$s=$pdo->prepare($sql); $s->execute($params); $rows=$s->fetchAll();
$counts=['Present'=>0,'Late'=>0,'Absent'=>0,'On Leave'=>0,'Rest Day'=>0]; foreach($rows as $r) if(isset($counts[$r['status']])) $counts[$r['status']]++;
?>
