<main class="main-content"><header class="topbar"><div><span class="eyebrow">ATTENDANCE ANALYTICS</span><h1>Reports</h1></div><button class="btn primary no-print" onclick="window.print()">Print report</button></header>
<section class="panel report-filter no-print"><div class="panel-heading"><div><h2>Report filters</h2><p class="muted">Choose a date range and optionally one employee.</p></div></div><form method="get" class="filter-form"><label>From<input type="date" name="from" value="<?=h($from)?>" required></label><label>To<input type="date" name="to" value="<?=h($to)?>" required></label><label>Employee<select name="employee_id"><option value="0">All employees</option><?php foreach($employees as $e): ?><option value="<?=(int)$e['id']?>" <?=$employee===(int)$e['id']?'selected':''?>><?=h($e['full_name'])?></option><?php endforeach; ?></select></label><button class="btn primary">Generate</button><a class="btn secondary" href="reports.php">Reset</a></form></section>
<section class="report-heading"><h2>GASATTEND Attendance Report</h2><p>Period: <?=h(date('M j, Y',strtotime($from)))?> – <?=h(date('M j, Y',strtotime($to)))?></p><p>Generated: <?=h(date('M j, Y g:i A'))?></p></section>
<section class="stats-grid report-stats"><?php foreach($counts as $label=>$count): ?><article class="stat-card compact"><div><p><?=h($label)?></p><strong><?=$count?></strong></div></article><?php endforeach; ?></section>
<section class="panel"><div class="panel-heading"><div><h2>Attendance details</h2><p class="muted"><?=count($rows)?> record(s)</p></div><button class="btn secondary no-print" id="export-csv">Export CSV</button></div>
<div class="table-wrap"><table id="report-table"><thead><tr><th>Date</th><th>Employee no.</th><th>Employee name</th><th>Time in</th><th>Time out</th><th>Status</th><th>Notes</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?=h($r['attendance_date'])?></td><td><?=h($r['employee_no'])?></td><td><?=h($r['full_name'])?></td><td><?=h($r['time_in']?date('g:i A',strtotime($r['time_in'])):'—')?></td><td><?=h($r['time_out']?date('g:i A',strtotime($r['time_out'])):'—')?></td><td><?=h($r['status'])?></td><td><?=h($r['notes'])?></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="7">No attendance records found for this filter.</td></tr><?php endif; ?></tbody></table></div></section>
